quickStart.sql:
SET VARIABLE qf_feed = 'wss://stream.example.com/events';
CALL radio_subscribe(getvariable('qf_feed'));
CALL radio_listen(true, INTERVAL '2 seconds');
SELECT receive_time, channel, message
FROM radio_subscription_received_messages(getvariable('qf_feed'))
ORDER BY receive_time DESC
LIMIT 10;
CALL radio_unsubscribe(getvariable('qf_feed'));
